* { box-sizing: border-box; }

:root {
  color-scheme: dark;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  background: #101a25;
  color: #edf3dc;
}

body {
  min-height: 100vh;
  margin: 0;
  display: grid;
  place-items: center;
  padding: 24px 16px;
  background-color: #101a25;
  background-image: radial-gradient(#314251 1px, transparent 1px);
  background-size: 20px 20px;
}

.lock-card {
  width: min(100%, 440px);
  padding: clamp(24px, 7vw, 40px);
  text-align: center;
  border: 2px solid #405465;
  border-radius: 14px;
  background: #1b2a38;
  box-shadow: 8px 8px 0 #0b1118;
}

.eyebrow { color: #83d6bd; font-size: .8rem; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 12px 0 8px; font-size: clamp(1.7rem, 7vw, 2.25rem); line-height: 1.15; }
.intro { margin: 0; color: #c0ccca; }

.dials {
  display: flex;
  justify-content: center;
  gap: clamp(12px, 5vw, 24px);
  margin: 30px 0 26px;
}

.dial {
  display: grid;
  justify-items: center;
  gap: 8px;
  width: clamp(74px, 22vw, 92px);
  padding: 12px 8px;
  border: 1px solid #405465;
  border-radius: 10px;
  background: #14212d;
}

.step-button, .open-button {
  min-height: 44px;
  border: 2px solid #83d6bd;
  border-radius: 7px;
  background: #233b47;
  color: #edf3dc;
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  transition: background-color .15s, transform .15s, box-shadow .15s;
}
.step-button { width: 100%; }
.step-button:hover, .open-button:hover { background: #315563; }
.step-button:active, .open-button:active { transform: translateY(2px); box-shadow: none; }
.step-button:focus-visible, .open-button:focus-visible { outline: 3px solid #f2c76e; outline-offset: 3px; }

.digit {
  display: grid;
  place-items: center;
  width: 100%;
  min-height: 60px;
  border: 1px solid #405465;
  border-radius: 6px;
  background: #0e1821;
  color: #f2c76e;
  font-family: ui-monospace, monospace;
  font-size: 2.25rem;
  font-weight: 800;
}

.open-button { width: 100%; min-height: 52px; background: #83d6bd; color: #10212a; letter-spacing: .08em; box-shadow: 0 4px 0 #4b9985; }
.open-button:hover { background: #a0ead2; }
.message { min-height: 1.5em; margin: 20px 0; color: #c0ccca; }
.message.success { color: #83d6bd; font-weight: 800; }
.message.error { color: #f2c76e; }
.attempts { display: flex; align-items: center; justify-content: center; gap: 10px; padding-top: 18px; border-top: 1px solid #405465; color: #c0ccca; font-size: .85rem; font-weight: 800; letter-spacing: .08em; }
.attempts strong { color: #f2c76e; font-size: 1.1rem; }

const dials = [...document.querySelectorAll('.dial')];
const digits = dials.map((dial) => dial.querySelector('.digit'));
const message = document.querySelector('#message');
const attemptCount = document.querySelector('#attempt-count');
let combination = [0, 0, 0];
let failedAttempts = 0;

for (const dial of dials) {
  dial.addEventListener('click', (event) => {
    const button = event.target.closest('button[data-step]');
    if (!button) return;

    const index = Number(dial.dataset.dial);
    const change = button.dataset.step === 'up' ? 1 : -1;
    combination[index] = (combination[index] + change + 10) % 10;
    digits[index].textContent = combination[index];
    message.textContent = 'The vault is waiting.';
    message.className = 'message';
  });
}

document.querySelector('#open-button').addEventListener('click', () => {
  if (combination.join('') === '372') {
    message.textContent = 'ACCESS GRANTED — the vault is open!';
    message.className = 'message success';
  } else {
    failedAttempts += 1;
    attemptCount.textContent = failedAttempts;
    message.textContent = 'Access denied. Try another combination.';
    message.className = 'message error';
  }
});
